  var data = [{d:"Feb 28",v:4150},{d:"Mar 10",v:4098},{d:"Mar 21",v:4280},{d:"Apr 1",v:4350},{d:"Apr 7",v:4310},{d:"Apr 14",v:4792},{d:"Apr 21",v:4680},{d:"Apr 29",v:4610},{d:"May 8",v:4453},{d:"May 15",v:4520},{d:"May 22",v:4610},{d:"May 29",v:4773},{d:"Jun 5",v:4500},{d:"Jun 10",v:4448},{d:"Jun 17",v:4380},{d:"Jun 19",v:4224},{d:"Jun 23",v:4150},{d:"Jun 26",v:4050},{d:"Jun 29",v:4037}];
