  });
  var bandStart = 16, bandEnd = 18;
  svg.appendChild(el("rect",{x:xp(bandStart),y:margin.top,width:xp(bandEnd)-xp(bandStart),height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(el("text",{x:(xp(bandStart)+xp(bandEnd))/2,y:margin.top+12,"text-anchor":"middle","font-size":"7","font-weight":"700","fill":"#c0392b"}, "HORMUZ CLASHES RESUME"));
  var warshX = xp(14);
  svg.appendChild(el("line",{x1:warshX,x2:warshX,y1:margin.top,y2:margin.top+PH,stroke:"#1a3560","stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
  svg.appendChild(el("text",{x:warshX+3,y:margin.top+20,"font-size":"7","font-weight":"700","fill":"#1a3560"}, "WARSH"));
  svg.appendChild(el("text",{x:warshX+3,y:margin.top+29,"font-size":"7","font-weight":"700","fill":"#1a3560"}, "1ST FOMC"));
  var pathD = "";
  data.forEach(function(pt,i){
    var x = xp(i), y = yp(pt.v);
    pathD += (i===0 ? "M" : "L") + x + "," + y + " ";
  });
  svg.appendChild(el("path",{d:pathD, fill:"none", stroke:"#8a3030", "stroke-width":"2"}));
  var lastX = xp(n-1), lastY = yp(data[n-1].v);
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  var pillW = 58, pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH/2;
  if (pillX < margin.left) pillX = lastX + 6;
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:3,fill:"#e8a825"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+4,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111111"}, "$4,037"));
  var container = _cs ? _cs.parentNode : null;
  if (container) container.appendChild(svg);
})();
